create table vzc.pilot_registry (
 pilot_id uuid primary key default gen_random_uuid(), pilot_code text not null unique, pilot_class text not null check (pilot_class in ('municipal_safety_corridor','logistics_freight_corridor','campus_research_mobility','emergency_response_corridor','fleet_safety','infrastructure_safety','other')), scope_reference text not null, deployment_gate_id uuid references vzc.deployment_authorization_gates(deployment_gate_id) on delete restrict, research_validation_record_id uuid references vzc.research_validation_records(validation_record_id) on delete restrict, pilot_state text not null default 'candidate' check (pilot_state in ('candidate','feasibility','evidence_complete','integration_designed','prototype','pilot_approved','pilot_active','evaluation','closed','scale_recommended','scale_not_recommended')), operational_owner_ref text, governance_approval_reference text, authority_reference text, safety_case_reference text, start_at timestamptz, end_at timestamptz, provenance jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (pilot_state not in ('pilot_approved','pilot_active','evaluation','closed','scale_recommended','scale_not_recommended') or (deployment_gate_id is not null and operational_owner_ref is not null and governance_approval_reference is not null and authority_reference is not null and safety_case_reference is not null)), check (end_at is null or start_at is null or end_at > start_at));
create table vzc.pilot_metric_definitions (pilot_metric_definition_id uuid primary key default gen_random_uuid(), pilot_id uuid not null references vzc.pilot_registry(pilot_id) on delete restrict, metric_code text not null, metric_name text not null, metric_family text not null check (metric_family in ('fatality','serious_injury','crash','near_miss','exposure','speed','response_time','infrastructure_risk','equity','operational','other')), unit text not null, methodology_reference text not null, baseline_required boolean not null default true, target_value numeric, target_direction text check (target_direction in ('increase','decrease','maintain','informational')), source_metric_schema text, source_metric_table text, source_metric_code text, created_at timestamptz not null default now(), unique(pilot_id,metric_code));
create table vzc.pilot_metric_observations (pilot_metric_observation_id uuid primary key default gen_random_uuid(), pilot_metric_definition_id uuid not null references vzc.pilot_metric_definitions(pilot_metric_definition_id) on delete restrict, measurement_kind text not null check (measurement_kind in ('baseline','during_pilot','post_pilot','comparison','correction')), metric_value numeric not null, measured_at timestamptz not null, evidence_reference text not null, source_event_reference text, confidence_score numeric check (confidence_score is null or (confidence_score >= 0 and confidence_score <= 1)), provenance jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table vzc.pilot_outcome_evaluations (pilot_outcome_evaluation_id uuid primary key default gen_random_uuid(), pilot_id uuid not null references vzc.pilot_registry(pilot_id) on delete restrict, evaluation_state text not null default 'planned' check (evaluation_state in ('planned','active','positive','negative','mixed','inconclusive','invalidated','superseded')), evaluation_method_reference text not null, evidence_reference text, reviewer_authority_ref text, safety_outcome_summary jsonb not null default '{}'::jsonb, adverse_outcomes_identified boolean not null default false, completed_at timestamptz, created_at timestamptz not null default now(), check (evaluation_state not in ('positive','negative','mixed','inconclusive','invalidated') or (evidence_reference is not null and reviewer_authority_ref is not null and completed_at is not null)));
create table vzc.pilot_scale_decisions (pilot_scale_decision_id uuid primary key default gen_random_uuid(), pilot_id uuid not null references vzc.pilot_registry(pilot_id) on delete restrict, pilot_outcome_evaluation_id uuid not null references vzc.pilot_outcome_evaluations(pilot_outcome_evaluation_id) on delete restrict, decision text not null check (decision in ('iterate','close','scale_recommended','scale_not_recommended','production_approved')), evidence_reference text not null, governance_approval_reference text, production_authority_reference text, commercial_reference text, created_at timestamptz not null default now(), check (decision <> 'production_approved' or (governance_approval_reference is not null and production_authority_reference is not null)));
create index vzc_pilot_registry_state_idx on vzc.pilot_registry(pilot_state,pilot_class); create index vzc_pilot_metric_definition_pilot_idx on vzc.pilot_metric_definitions(pilot_id,metric_family); create index vzc_pilot_metric_observation_metric_idx on vzc.pilot_metric_observations(pilot_metric_definition_id,measured_at); create index vzc_pilot_outcome_pilot_idx on vzc.pilot_outcome_evaluations(pilot_id,evaluation_state); create index vzc_pilot_scale_pilot_idx on vzc.pilot_scale_decisions(pilot_id,decision);
alter table vzc.pilot_registry enable row level security; alter table vzc.pilot_metric_definitions enable row level security; alter table vzc.pilot_metric_observations enable row level security; alter table vzc.pilot_outcome_evaluations enable row level security; alter table vzc.pilot_scale_decisions enable row level security;
revoke all on table vzc.pilot_registry,vzc.pilot_metric_definitions,vzc.pilot_metric_observations,vzc.pilot_outcome_evaluations,vzc.pilot_scale_decisions from anon,authenticated; grant select,insert,update,delete on vzc.pilot_registry,vzc.pilot_metric_definitions,vzc.pilot_metric_observations,vzc.pilot_outcome_evaluations,vzc.pilot_scale_decisions to service_role;
create policy vzc_pilot_registry_service_role_all on vzc.pilot_registry for all to service_role using (true) with check (true); create policy vzc_pilot_metric_definition_service_role_all on vzc.pilot_metric_definitions for all to service_role using (true) with check (true); create policy vzc_pilot_metric_observation_service_role_all on vzc.pilot_metric_observations for all to service_role using (true) with check (true); create policy vzc_pilot_outcome_service_role_all on vzc.pilot_outcome_evaluations for all to service_role using (true) with check (true); create policy vzc_pilot_scale_service_role_all on vzc.pilot_scale_decisions for all to service_role using (true) with check (true);
comment on table vzc.pilot_registry is 'VZC bounded pilot registry. Pilot activity does not imply production approval or authority beyond the explicit deployment gate.'; comment on table vzc.pilot_metric_definitions is 'Pilot-specific Vision Zero measurement contract; may reference authoritative shared impact metric registries rather than duplicate them.'; comment on table vzc.pilot_metric_observations is 'Evidence-backed pilot measurements including baseline, during-pilot, post-pilot, comparison and correction observations.'; comment on table vzc.pilot_outcome_evaluations is 'Governed evaluation preserving positive, negative, mixed and inconclusive safety outcomes.'; comment on table vzc.pilot_scale_decisions is 'Scale and production decisions remain distinct from pilot success and require explicit production governance and authority.';